# Agent loop (conceptual)
tools = {
    "calculator": lambda x: eval(x),
    "search": lambda q: f"search results for: {q}",
}

def agent_loop(task, llm, tools, max_steps=5):
    history = [f"Task: {task}"]
    for step in range(max_steps):
        decision = llm.decide(history, available_tools=list(tools.keys()))
        if decision["type"] == "finish":
            return decision["answer"]
        tool_name = decision["tool"]
        result = tools[tool_name](decision["input"])
        history.append(f"Used {tool_name}: {result}")
    return "max steps reached"

print("Agent loop: decide, act, observe, repeat")

# Agentic workflow design principles
design = {
    "tools":         "simple, well-named, well-documented",
    "guardrails":    "max iterations, timeouts, validation",
    "observability": "log every decision and tool call",
    "fallbacks":     "graceful degradation when tools fail",
}

for principle, detail in design.items():
    print(f"{principle}: {detail}")

